parameters.jsCode:
const aiResponse = $input.item.json.message.content;
let brief;
try {
  brief = JSON.parse(aiResponse);
} catch (e) {
  brief = { error: 'Parse failed', raw: aiResponse };
}

return {
  json: {
    report_type: 'creative_brief',
    generated_at: new Date().toISOString(),
    agent_id: 'marketing-strategist',
    workflow_id: 'WF-STRATEGY-BRIEF',
    brief,
    request: $('Webhook Brief Request').item.json.body
  }
};

